drop extension if exists "pg_net";


  create table "public"."circle_participants" (
    "id" bigint generated by default as identity not null,
    "circle_id" uuid not null,
    "user_id" uuid not null,
    "role" text default 'player'::text,
    "score" integer default 0,
    "is_ready" boolean default false,
    "joined_at" timestamp with time zone default now()
      );


alter table "public"."circle_participants" enable row level security;


  create table "public"."circles" (
    "id" uuid not null default gen_random_uuid(),
    "host_id" uuid not null,
    "name" text not null,
    "from_lang" text not null,
    "to_lang" text not null,
    "mode" text not null,
    "level" text not null,
    "max_players" integer default 5,
    "questions_count" integer default 15,
    "time_per_q" integer default 10,
    "allow_spectators" boolean default true,
    "status" text default 'lobby'::text,
    "created_at" timestamp with time zone default now(),
    "questions" jsonb default '[]'::jsonb
      );


alter table "public"."circles" enable row level security;


  create table "public"."courses" (
    "id" text not null,
    "title" text not null,
    "subtitle" text,
    "icon_url" text,
    "source_lang" text,
    "target_lang" text
      );


alter table "public"."courses" enable row level security;


  create table "public"."friendships" (
    "id" bigint generated by default as identity not null,
    "requester_id" uuid not null,
    "addressee_id" uuid not null,
    "status" text default 'pending'::text,
    "created_at" timestamp with time zone default now()
      );


alter table "public"."friendships" enable row level security;


  create table "public"."messages" (
    "id" bigint generated by default as identity not null,
    "sender_id" uuid not null,
    "receiver_id" uuid not null,
    "content" text not null,
    "created_at" timestamp with time zone default now()
      );


alter table "public"."messages" enable row level security;


  create table "public"."notifications" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "type" text,
    "title" text,
    "body" text,
    "is_read" boolean default false,
    "metadata" jsonb default '{}'::jsonb,
    "created_at" timestamp with time zone default now()
      );


alter table "public"."notifications" enable row level security;


  create table "public"."profiles" (
    "id" uuid not null,
    "username" text,
    "display_name" text,
    "full_name" text,
    "avatar_url" text,
    "website" text,
    "bio" text,
    "location" text,
    "total_xp" integer default 0,
    "settings" jsonb default '{}'::jsonb,
    "updated_at" timestamp with time zone
      );


alter table "public"."profiles" enable row level security;


  create table "public"."sentences" (
    "id" bigint generated by default as identity not null,
    "course_id" text,
    "original" text not null,
    "translation" text not null,
    "difficulty" integer default 1
      );


alter table "public"."sentences" enable row level security;


  create table "public"."user_courses" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "course_id" text not null,
    "progress_xp" integer default 0,
    "last_accessed" timestamp with time zone default now()
      );


alter table "public"."user_courses" enable row level security;


  create table "public"."vocabulary" (
    "id" bigint generated by default as identity not null,
    "course_id" text,
    "word" text not null,
    "translation" text not null,
    "usage_example" text,
    "difficulty" integer default 1
      );


alter table "public"."vocabulary" enable row level security;

CREATE UNIQUE INDEX circle_participants_circle_id_user_id_key ON public.circle_participants USING btree (circle_id, user_id);

CREATE UNIQUE INDEX circle_participants_pkey ON public.circle_participants USING btree (id);

CREATE UNIQUE INDEX circles_pkey ON public.circles USING btree (id);

CREATE UNIQUE INDEX courses_pkey ON public.courses USING btree (id);

CREATE UNIQUE INDEX friendships_pkey ON public.friendships USING btree (id);

CREATE UNIQUE INDEX messages_pkey ON public.messages USING btree (id);

CREATE UNIQUE INDEX notifications_pkey ON public.notifications USING btree (id);

CREATE UNIQUE INDEX profiles_pkey ON public.profiles USING btree (id);

CREATE UNIQUE INDEX profiles_username_key ON public.profiles USING btree (username);

CREATE UNIQUE INDEX sentences_pkey ON public.sentences USING btree (id);

CREATE UNIQUE INDEX user_courses_pkey ON public.user_courses USING btree (id);

CREATE UNIQUE INDEX user_courses_user_id_course_id_key ON public.user_courses USING btree (user_id, course_id);

CREATE UNIQUE INDEX vocabulary_pkey ON public.vocabulary USING btree (id);

