alter table "public"."vocabulary" add constraint "vocabulary_pkey" PRIMARY KEY using index "vocabulary_pkey";

alter table "public"."circle_participants" add constraint "circle_participants_circle_id_fkey" FOREIGN KEY (circle_id) REFERENCES public.circles(id) ON DELETE CASCADE not valid;

alter table "public"."circle_participants" validate constraint "circle_participants_circle_id_fkey";

alter table "public"."circle_participants" add constraint "circle_participants_circle_id_user_id_key" UNIQUE using index "circle_participants_circle_id_user_id_key";

alter table "public"."circle_participants" add constraint "circle_participants_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id) not valid;

alter table "public"."circle_participants" validate constraint "circle_participants_user_id_fkey";

alter table "public"."circles" add constraint "circles_host_id_fkey" FOREIGN KEY (host_id) REFERENCES public.profiles(id) not valid;

alter table "public"."circles" validate constraint "circles_host_id_fkey";

alter table "public"."friendships" add constraint "friendships_addressee_id_fkey" FOREIGN KEY (addressee_id) REFERENCES public.profiles(id) not valid;

alter table "public"."friendships" validate constraint "friendships_addressee_id_fkey";

alter table "public"."friendships" add constraint "friendships_requester_id_fkey" FOREIGN KEY (requester_id) REFERENCES public.profiles(id) not valid;

alter table "public"."friendships" validate constraint "friendships_requester_id_fkey";

alter table "public"."messages" add constraint "messages_receiver_id_fkey" FOREIGN KEY (receiver_id) REFERENCES public.profiles(id) not valid;

alter table "public"."messages" validate constraint "messages_receiver_id_fkey";

alter table "public"."messages" add constraint "messages_sender_id_fkey" FOREIGN KEY (sender_id) REFERENCES public.profiles(id) not valid;

alter table "public"."messages" validate constraint "messages_sender_id_fkey";

alter table "public"."notifications" add constraint "notifications_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id) not valid;

alter table "public"."notifications" validate constraint "notifications_user_id_fkey";

alter table "public"."profiles" add constraint "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) not valid;

alter table "public"."profiles" validate constraint "profiles_id_fkey";

alter table "public"."profiles" add constraint "profiles_username_key" UNIQUE using index "profiles_username_key";

alter table "public"."sentences" add constraint "sentences_course_id_fkey" FOREIGN KEY (course_id) REFERENCES public.courses(id) not valid;

alter table "public"."sentences" validate constraint "sentences_course_id_fkey";

alter table "public"."user_courses" add constraint "user_courses_course_id_fkey" FOREIGN KEY (course_id) REFERENCES public.courses(id) not valid;

alter table "public"."user_courses" validate constraint "user_courses_course_id_fkey";

alter table "public"."user_courses" add constraint "user_courses_user_id_course_id_key" UNIQUE using index "user_courses_user_id_course_id_key";

alter table "public"."user_courses" add constraint "user_courses_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id) not valid;

alter table "public"."user_courses" validate constraint "user_courses_user_id_fkey";

alter table "public"."vocabulary" add constraint "vocabulary_course_id_fkey" FOREIGN KEY (course_id) REFERENCES public.courses(id) not valid;

alter table "public"."vocabulary" validate constraint "vocabulary_course_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.profiles (id, username, full_name, avatar_url)
  values (new.id, new.raw_user_meta_data->>'username', new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'avatar_url')
  on conflict (id) do nothing;
  return new;
end;
$function$
;

create or replace view "public"."leaderboard" as  SELECT id,
    username,
    display_name,
    avatar_url,
    total_xp AS xp
   FROM public.profiles
  ORDER BY total_xp DESC;


