  create policy "Participants viewable by everyone."
  on "public"."circle_participants"
  as permissive
  for select
  to public
using (true);



  create policy "Users can join circles."
  on "public"."circle_participants"
  as permissive
  for insert
  to public
with check ((auth.uid() = user_id));



  create policy "Users can leave circles."
  on "public"."circle_participants"
  as permissive
  for delete
  to public
using ((auth.uid() = user_id));



  create policy "Users can update their own status."
  on "public"."circle_participants"
  as permissive
  for update
  to public
using ((auth.uid() = user_id));



  create policy "Authenticated users can create circles."
  on "public"."circles"
  as permissive
  for insert
  to public
with check ((auth.uid() = host_id));



  create policy "Circles are viewable by everyone."
  on "public"."circles"
  as permissive
  for select
  to public
using (true);



  create policy "Host can update their circle."
  on "public"."circles"
  as permissive
  for update
  to public
using ((auth.uid() = host_id));



  create policy "Courses are viewable by everyone."
  on "public"."courses"
  as permissive
  for select
  to public
using (true);



  create policy "Users can delete their own friendships"
  on "public"."friendships"
  as permissive
  for delete
  to public
using (((auth.uid() = requester_id) OR (auth.uid() = addressee_id)));



  create policy "Users can insert friendships"
  on "public"."friendships"
  as permissive
  for insert
  to public
with check ((auth.uid() = requester_id));



  create policy "Users can update their own friendships"
  on "public"."friendships"
  as permissive
  for update
  to public
using (((auth.uid() = requester_id) OR (auth.uid() = addressee_id)));



  create policy "Users can view their own friendships"
  on "public"."friendships"
  as permissive
  for select
  to public
using (((auth.uid() = requester_id) OR (auth.uid() = addressee_id)));



  create policy "Users can insert messages"
  on "public"."messages"
  as permissive
  for insert
  to public
with check ((auth.uid() = sender_id));



  create policy "Users can view their own messages"
  on "public"."messages"
  as permissive
  for select
  to public
using (((auth.uid() = sender_id) OR (auth.uid() = receiver_id)));



  create policy "Users can delete their own notifications"
  on "public"."notifications"
  as permissive
  for delete
  to public
using ((auth.uid() = user_id));



  create policy "Users can update their own notifications"
  on "public"."notifications"
  as permissive
  for update
  to public
using ((auth.uid() = user_id));



  create policy "Users can view their own notifications"
  on "public"."notifications"
  as permissive
  for select
  to public
using ((auth.uid() = user_id));



  create policy "Public profiles are viewable by everyone."
  on "public"."profiles"
  as permissive
  for select
  to public
using (true);



  create policy "Users can insert their own profile."
  on "public"."profiles"
  as permissive
  for insert
  to public
with check ((auth.uid() = id));



  create policy "Users can update own profile."
  on "public"."profiles"
  as permissive
  for update
  to public
using ((auth.uid() = id));



  create policy "Sentences are viewable by everyone."
  on "public"."sentences"
  as permissive
  for select
  to public
using (true);



  create policy "Users can update own course progress."
  on "public"."user_courses"
  as permissive
  for all
  to public
using ((auth.uid() = user_id));



  create policy "Users can view own course progress."
  on "public"."user_courses"
  as permissive
  for select
  to public
using ((auth.uid() = user_id));



  create policy "Vocabulary is viewable by everyone."
  on "public"."vocabulary"
  as permissive
  for select
  to public
using (true);


CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

CREATE TRIGGER objects_delete_delete_prefix AFTER DELETE ON storage.objects FOR EACH ROW EXECUTE FUNCTION storage.delete_prefix_hierarchy_trigger();

CREATE TRIGGER objects_insert_create_prefix BEFORE INSERT ON storage.objects FOR EACH ROW EXECUTE FUNCTION storage.objects_insert_prefix_trigger();

CREATE TRIGGER objects_update_create_prefix BEFORE UPDATE ON storage.objects FOR EACH ROW WHEN (((new.name <> old.name) OR (new.bucket_id <> old.bucket_id))) EXECUTE FUNCTION storage.objects_update_prefix_trigger();

CREATE TRIGGER prefixes_create_hierarchy BEFORE INSERT ON storage.prefixes FOR EACH ROW WHEN ((pg_trigger_depth() < 1)) EXECUTE FUNCTION storage.prefixes_insert_trigger();

CREATE TRIGGER prefixes_delete_hierarchy AFTER DELETE ON storage.prefixes FOR EACH ROW EXECUTE FUNCTION storage.delete_prefix_hierarchy_trigger();


